import{_ as i,l as n,o as e,c as s,v as t,p,x as r,d as l,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"最大熵原理","description":"","frontmatter":{"title":"最大熵原理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/max-entropy-principle.md","filePath":"cs/max-entropy-principle.md","lastUpdated":1789023840000}'),h={name:"cs/max-entropy-principle.md"};function c(_,a,u,f,b,x){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="最大熵原理" tabindex="-1">最大熵原理 <a class="header-anchor" href="#最大熵原理" aria-label="Permalink to &quot;最大熵原理&quot;">​</a></h1><div class="epigraph"><p>只知道若干期望约束时，选使 $H$ 最大的 $p$——等价于相对均匀分布的 KL 最小；指数族由此出现。</p><footer>—— 据 Jaynes, Information Theory and Statistical Mechanics, 1957；Cover and Thomas 整理</footer></div><p>上一课<a href="/cs/kl-cross-entropy">KL 与交叉熵</a> 给出 \\(D(p\\|q)\\)。缺口是<strong>选分布</strong>：约束 \\(\\mathbb{E}_p[f_i]=a_i\\)，其余未知。Jaynes：最大化 \\(H(p)\\)，或 \\(\\min D(p\\|u)\\)（\\(u\\) 均匀）。拉格朗日得 \\(p(x)\\propto\\exp(\\sum\\lambda_i f_i(x))\\)。信息单元以此收束，下一单元数论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>约束不足时，分布不唯一。再人为加峰会引入没有证据的信息（KL 意义下相对均匀更远）。最大熵选最平的那个。有均值约束的实直线上得指数分布；有均值方差得高斯——在给定支撑与测度下。离散字母表上，无约束即均匀，熵最大 \\(\\log|\\mathcal{X}|\\)，与<a href="/cs/entropy-bits">熵课</a> 一致。</p><p>不是「自然界最大化熵」的物理学断言；本课当推理规则。统计力学是 Jaynes 的动机，不是本栏主线。</p><h3 id="不是最大似然的别名" tabindex="-1">不是最大似然的别名 <a class="header-anchor" href="#不是最大似然的别名" aria-label="Permalink to &quot;不是最大似然的别名&quot;">​</a></h3><p>有了完整 i.i.d. 样本，MLE 另说。最大熵用于<strong>矩约束</strong>而非整份经验分布。经验分布本身已是一种最大熵（无额外约束时在类型上）。</p><p><span class="marginnote">Jaynes 1957。Cover–Thomas 第 12 章。Csiszár 的 \\(I\\)-投影：约束凸集上最小 KL。本课不把 CRF 特征当主例子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写拉格朗日：\\(H+\\sum\\lambda_i(\\mathbb{E}f_i-a_i)\\)。指出解在指数族。对偶：\\(\\lambda\\) 使约束满足。强调：换参考测度 \\(q_0\\) 则 \\(\\min D(p\\|q_0)\\)，指数里多一个 \\(\\log q_0\\)。</p>',11)),(e(),p(m,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CONS%5B%22%E7%9F%A9%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20MAXH%5B%22max%20H(p)%22%5D%0A%20%20MAXH%20--%3E%20EXP%5B%22%E6%8C%87%E6%95%B0%E6%97%8F%20p%20%E2%88%9D%20e%5E%7B%CE%BB%C2%B7f%7D%22%5D%0A%20%20EXP%20--%3E%20KLMIN%5B%22%3D%20min%20D(p%7C%7C%E5%9D%87%E5%8C%80)%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信息与编码课序结束：信源、信道、有损、相对熵、选分布。后文密码数论不再用 \\(R(D)\\)，除非点名。最大熵给「缺省分布」一个信息论名字，避免在逻辑单元用概率时偷偷换先验而不声明。</p><p>与 Kolmogorov：最大熵是分布层；\\(K\\) 是单串。</p><p>\\(I\\)-投影：在凸约束集上 \\(\\min D(p\\|q_0)\\) 唯一（严格凸）。最大熵是 \\(q_0\\) 均匀的特例。经验矩当约束时，解随样本变，这是统计，不是再定义 \\(H\\)。信息单元到此：五把尺子 \\(H,C,R(D),D,\\max H\\) 都有了。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证大偏差的 Sanov 全文，不引入热力学极限。不把机器学习的正则当 Jaynes。后课默认：只有矩时，缺省 \\(p\\) 是最大熵指数族。下一课模运算，为密码准备。</p><p>约束不足时最大熵给缺省分布，不是声称物理系统在最大化 \\(H\\)。指数族由拉格朗日出现。下一单元改做模算术，不再用 \\(R(D)\\)。</p><p>上一课留下的缺口在本课收口；「最大熵原理」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>矩约束下选 \\(\\max H\\) 的 \\(p\\)，得指数族。</li><li>等价于相对均匀（或参考测度）的最小 KL。</li><li>是推理规则，不是物理定律课。</li><li>出处：Jaynes, 1957；Cover and Thomas。</li></ul>',10))])}const q=i(h,[["render",c]]);export{D as __pageData,q as default};
